<?php require_once __DIR__ . '/../includes/order_service.php'; require_once __DIR__ . '/../includes/auth.php'; admin_header('Order View'); $id=(int)($_GET['id']??$_POST['id']??0); if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); update_order_status($id,$_POST['status'],$_POST['note'] ?? '',current_user()['id']); } $order=db_fetch('SELECT o.*,pc.case_code,p.full_name,p.phone,p.whatsapp,pr.prescription_code FROM orders o JOIN patient_cases pc ON pc.id=o.case_id JOIN patients p ON p.id=o.patient_id LEFT JOIN prescriptions pr ON pr.id=o.prescription_id WHERE o.id=?',[$id]); if(!$order){ echo empty_state('Order not found.'); admin_footer(); exit; } $logs=db_fetch_all('SELECT osl.*,u.name user_name FROM order_status_logs osl LEFT JOIN users u ON u.id=osl.changed_by WHERE order_id=? ORDER BY id DESC',[$id]); $msg='Homeo Tabeeb confirmation: Patient '.$order['full_name'].', Case '.$order['case_code'].', Order '.$order['order_code'].'. Please confirm delivery address and Cash on Delivery medicine order.'; ?><div class="row g-3"><div class="col-lg-7"><div class="card soft-card"><div class="card-body"><h3><?= e($order['order_code']) ?></h3><p>Patient: <?= e($order['full_name']) ?> | <?= e($order['delivery_phone']) ?></p><p>Address: <?= e($order['delivery_address']) ?>, <?= e($order['city']) ?></p><p>Status: <strong><?= e($order['status']) ?></strong></p><a class="btn btn-success" target="_blank" href="<?= e(wa_link($order['delivery_whatsapp'],$msg)) ?>">Open WhatsApp Confirmation</a><form method="post" class="mt-4"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><label>Update status</label><select name="status" class="form-select mb-2"><?php foreach(['requested','pending_doctor_verification','approved','contacted','sent_to_vendor','out_for_delivery','delivered','cancelled','rejected'] as $s): ?><option <?= $order['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><textarea name="note" class="form-control mb-2" placeholder="Status note"></textarea><button class="btn btn-teal">Save Status</button></form></div></div></div><div class="col-lg-5"><div class="card soft-card"><div class="card-body"><h4>Status Logs</h4><?php foreach($logs as $l): ?><p><strong><?= e($l['status']) ?></strong><br><small><?= e($l['created_at']) ?> <?= e($l['user_name'] ?? '') ?></small><br><?= e($l['note']) ?></p><?php endforeach; ?></div></div></div></div><?php admin_footer(); ?>
